<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <title>City Skyline Day-Night Cycle</title>
  <style>
    * { margin: 0; padding: 0; box-sizing: border-box; }
    body, html { width: 100%; height: 100%; overflow: hidden; background: #000; }
    canvas { display: block; width: 100vw; height: 100vh; }
  </style>
</head>
<body>
<canvas id="skyline"></canvas>

<script>
const canvas = document.getElementById('skyline');
const ctx = canvas.getContext('2d');

let W, H;
let stars = [];
let buildings = [];

function resize() {
  W = canvas.width = window.innerWidth;
  H = canvas.height = window.innerHeight;
  initWorld();
}

function initWorld() {
  // Generate random stars
  stars = [];
  for (let i = 0; i < 150; i++) {
    stars.push({
      x: Math.random() * W,
      y: Math.random() * (H * 0.65),
      r: Math.random() * 1.5 + 0.5,
      phase: Math.random() * Math.PI * 2
    });
  }

  // Generate buildings across layers
  buildings = [];
  const layers = [
    { count: 20, minH: 0.25, maxH: 0.55, color: [20, 24, 38], isBack: true },
    { count: 16, minH: 0.2, maxH: 0.45, color: [12, 14, 22], isBack: false }
  ];

  layers.forEach((layer) => {
    let x = -20;
    while (x < W + 40) {
      const w = Math.random() * 60 + 50;
      const h = H * (layer.minH + Math.random() * (layer.maxH - layer.minH));
      const b = {
        x: x,
        y: H - h,
        w: w,
        h: h,
        color: layer.color,
        isBack: layer.isBack,
        spire: Math.random() > 0.6,
        windows: []
      };

      if (!layer.isBack) {
        const rows = Math.floor((h - 30) / 16);
        const cols = Math.floor((w - 16) / 12);
        for (let r = 0; r < rows; r++) {
          for (let c = 0; c < cols; c++) {
            b.windows.push({
              x: x + 8 + c * 12,
              y: H - h + 15 + r * 16,
              w: 6,
              h: 9,
              litChance: Math.random(),
              warmth: Math.random()
            });
          }
        }
      }
      buildings.push(b);
      x += w - (Math.random() * 15 + 5);
    }
  });
}

// Sky color keyframes [time, topColor, bottomColor]
const skyKeyframes = [
  { t: 0.00, top: [2, 2, 8],     bot: [5, 5, 20] },     // Midnight
  { t: 0.15, top: [15, 10, 30],  bot: [60, 20, 45] },   // Pre-dawn
  { t: 0.25, top: [45, 30, 75],  bot: [240, 110, 60] }, // Sunrise
  { t: 0.35, top: [30, 120, 210],bot: [160, 215, 245] },// Morning
  { t: 0.50, top: [20, 100, 200],bot: [140, 200, 240] },// Noon
  { t: 0.65, top: [35, 80, 170], bot: [220, 150, 90] }, // Late Afternoon
  { t: 0.75, top: [40, 20, 60],  bot: [230, 80, 40] },  // Sunset
  { t: 0.85, top: [12, 10, 30],  bot: [40, 20, 50] },   // Dusk
  { t: 1.00, top: [2, 2, 8],     bot: [5, 5, 20] }      // Midnight
];

function lerpColor(c1, c2, f) {
  return [
    Math.round(c1[0] + (c2[0] - c1[0]) * f),
    Math.round(c1[1] + (c2[1] - c1[1]) * f),
    Math.round(c1[2] + (c2[2] - c1[2]) * f)
  ];
}

function getSkyColors(progress) {
  for (let i = 0; i < skyKeyframes.length - 1; i++) {
    const k1 = skyKeyframes[i];
    const k2 = skyKeyframes[i + 1];
    if (progress >= k1.t && progress <= k2.t) {
      const f = (progress - k1.t) / (k2.t - k1.t);
      return {
        top: lerpColor(k1.top, k2.top, f),
        bot: lerpColor(k1.bot, k2.bot, f)
      };
    }
  }
  return skyKeyframes[0];
}

function draw(timestamp) {
  const duration = 10000;
  const progress = (timestamp % duration) / duration;

  // Sky Background
  const sky = getSkyColors(progress);
  const grad = ctx.createLinearGradient(0, 0, 0, H);
  grad.addColorStop(0, `rgb(${sky.top.join(',')})`);
  grad.addColorStop(0.85, `rgb(${sky.bot.join(',')})`);
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, W, H);

  // Night factor: 1 at midnight, 0 at noon
  const nightFactor = Math.max(0, Math.min(1, (Math.cos(progress * Math.PI * 2) + 0.3) / 1.3));

  // Stars
  if (nightFactor > 0.05) {
    stars.forEach(s => {
      const twinkle = 0.5 + 0.5 * Math.sin(timestamp * 0.006 + s.phase);
      ctx.fillStyle = `rgba(255, 255, 255, ${nightFactor * twinkle * 0.9})`;
      ctx.beginPath();
      ctx.arc(s.x, s.y, s.r, 0, Math.PI * 2);
      ctx.fill();
    });
  }

  // Sun and Moon positions along an orbital path
  const orbitAngle = progress * Math.PI * 2 - Math.PI / 2; // Noon at 0.5
  const cx = W / 2;
  const cy = H * 0.75;
  const rx = W * 0.45;
  const ry = H * 0.55;

  const sunX = cx + rx * Math.cos(orbitAngle + Math.PI);
  const sunY = cy + ry * Math.sin(orbitAngle + Math.PI);
  const moonX = cx + rx * Math.cos(orbitAngle);
  const moonY = cy + ry * Math.sin(orbitAngle);

  // Draw Sun
  if (sunY < H + 60) {
    const sunGrad = ctx.createRadialGradient(sunX, sunY, 10, sunX, sunY, 60);
    sunGrad.addColorStop(0, 'rgba(255, 250, 220, 1)');
    sunGrad.addColorStop(0.3, 'rgba(255, 180, 50, 0.8)');
    sunGrad.addColorStop(1, 'rgba(255, 100, 0, 0)');
    ctx.fillStyle = sunGrad;
    ctx.beginPath();
    ctx.arc(sunX, sunY, 60, 0, Math.PI * 2);
    ctx.fill();
  }

  // Draw Moon
  if (moonY < H + 40) {
    ctx.save();
    ctx.shadowColor = 'rgba(220, 230, 255, 0.6)';
    ctx.shadowBlur = 20;
    ctx.fillStyle = '#f0f3f8';
    ctx.beginPath();
    ctx.arc(moonX, moonY, 22, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();

    // Crescent shadow
    ctx.fillStyle = `rgba(${sky.top.join(',')}, 0.92)`;
    ctx.beginPath();
    ctx.arc(moonX + 8, moonY - 3, 18, 0, Math.PI * 2);
    ctx.fill();
  }

  // Draw Skyline
  buildings.forEach(b => {
    // Ambient silhouette lighting shifts with the day/night state
    const shade = nightFactor > 0.5 ? 0.7 : 1.0;
    ctx.fillStyle = `rgb(${b.color[0] * shade}, ${b.color[1] * shade}, ${b.color[2] * shade})`;
    ctx.fillRect(b.x, b.y, b.w, b.h);

    // Rooftop Spire with beacon
    if (b.spire) {
      ctx.strokeStyle = '#111';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(b.x + b.w / 2, b.y);
      ctx.lineTo(b.x + b.w / 2, b.y - 25);
      ctx.stroke();

      // Blinking red beacon
      const blink = (Math.sin(timestamp * 0.008) > 0) ? 1 : 0.1;
      ctx.fillStyle = `rgba(255, 30, 30, ${blink * (0.3 + nightFactor * 0.7)})`;
      ctx.beginPath();
      ctx.arc(b.x + b.w / 2, b.y - 25, 2.5, 0, Math.PI * 2);
      ctx.fill();
    }

    // Windows
    if (!b.isBack) {
      b.windows.forEach(w => {
        const isLit = w.litChance < (nightFactor * 0.75 + 0.08);
        if (isLit && nightFactor > 0.15) {
          const warm = w.warmth > 0.3 ? '255, 214, 110' : '200, 230, 255';
          const alpha = Math.min(1, (nightFactor - 0.15) * 2);
          ctx.fillStyle = `rgba(${warm}, ${alpha})`;
        } else {
          ctx.fillStyle = 'rgba(25, 30, 45, 0.7)';
        }
        ctx.fillRect(w.x, w.y, w.w, w.h);
      });
    }
  });

  // Base ground line
  ctx.fillStyle = '#05070a';
  ctx.fillRect(0, H - 15, W, 15);

  requestAnimationFrame(draw);
}

window.addEventListener('resize', resize);
resize();
requestAnimationFrame(draw);
</script>
</body>
</html>
```

The animation calculates a repeating 10-second timeline using `requestAnimationFrame`, smoothly interpolating canvas sky gradients while tracing opposing orbital paths for the sun and moon, and dynamically drives the opacity of twinkling stars and individual window lights based on the calculated night intensity.
